{
  "positionId": "P01",
  "interviews": [
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "느린 조회 쿼리의 병목에 맞는 개선 방법을 선택할 수 있는지 검증한다. 실행 계획과 조회 조건을 근거로 인덱스 추가가 필요하다고 판단한 이유에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "운영 화면의 신고 목록 조회 쿼리에서 응답 지연이 발생한 상황이다.",
          "task": "조회 지연의 원인에 맞춰 인덱스 추가의 필요성을 판단해야 했다.",
          "action": "실행 계획과 조회 조건에서 확인한 사실을 바탕으로 인덱스 추가가 필요한 이유를 설명한다.",
          "result": "관찰한 병목과 인덱스 추가 판단 사이의 연결이 구체적으로 드러난다."
        },
        "expectedEvidence": [
          "인덱스 추가가 필요하다고 판단한 구체적인 근거",
          "그 판단의 바탕이 된 실행 계획의 접근 방식이나 조회 조건에 관한 관찰",
          "관찰한 병목을 인덱스 추가로 줄일 수 있다고 본 기술적 연결"
        ]
      },
      "question": "포켓마켓에서 신고 목록 조회를 3.2초에서 0.4초로 줄이셨던데요, 당시 인덱스 추가가 필요하다고 판단하신 근거는 뭐였어요?",
      "answerTip": "당시 상황을 떠올리며 차분히 답해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "인덱스 추가 판단의 근거를 실제 조회 쿼리의 특성과 연결해 구체적으로 설명한다.",
            "실행 계획의 접근 방식이나 조회 조건에서 확인한 사실을 명확히 제시한다.",
            "관찰한 병목을 인덱스가 줄이는 이유를 기술적으로 타당하게 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "인덱스 추가가 필요하다고 본 근거는 제시하지만 실제 쿼리와의 연결이 부분적이다.",
            "실행 계획이나 조회 조건에 관한 관찰은 있으나 구체성이 부족하다.",
            "인덱스와 병목의 관계를 대체로 설명하지만 판단의 연결에 일부 빈틈이 있다."
          ]
        },
        "poor": {
          "criteria": [
            "인덱스를 추가했다는 사실만 말하고 필요성을 판단한 근거는 제시하지 못한다.",
            "실행 계획이나 조회 조건에서 확인한 사실이 드러나지 않는다.",
            "관찰한 병목과 인덱스 추가의 관계를 설명하지 못하거나 기술적으로 맞지 않게 설명한다."
          ]
        }
      }
    },
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "운영 오류의 원인을 로그로 추적해 좁힐 수 있는지 검증한다. 알림 중복 발송을 스케줄러 중복 실행으로 특정하게 한 로그의 흔적에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓에서 배포 후 같은 알림이 두 번 발송되는 오류가 발생했다.",
          "task": "로그를 근거로 알림 중복 발송의 원인을 좁혀야 했다.",
          "action": "로그에서 확인한 실행 흔적과 시간적 관계를 근거로 스케줄러 중복 실행을 원인으로 판단한 내용을 설명한다.",
          "result": "로그의 구체적인 흔적이 스케줄러 중복 실행이라는 원인 판단으로 이어지는 연결이 드러난다."
        },
        "expectedEvidence": [
          "스케줄러 중복 실행으로 원인을 좁히게 한 구체적인 로그 흔적",
          "해당 흔적에서 확인한 실행 시점이나 서버별 실행 관계",
          "그 흔적이 알림 중복 발송의 원인을 설명한다고 판단한 연결"
        ]
      },
      "question": "포켓마켓에서 배포 후 알림 중복 발송 오류를 추적하셨던데요, 로그의 어떤 흔적을 보고 원인을 스케줄러 중복 실행으로 좁히셨어요?",
      "answerTip": "기억나는 장면을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "스케줄러 중복 실행을 가리킨 로그 흔적을 구체적으로 설명한다.",
            "로그에 나타난 실행 시점이나 서버별 실행 관계를 명확히 짚는다.",
            "해당 실행 흔적이 알림 중복 발송으로 이어진다는 원인 판단을 논리적으로 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "원인을 좁히는 데 사용한 로그 흔적은 제시하지만 구체성이 부족하다.",
            "실행 시점이나 서버별 실행 관계를 일부 설명한다.",
            "로그 흔적과 알림 중복 발송의 연결은 대체로 타당하지만 설명에 일부 빈틈이 있다."
          ]
        },
        "poor": {
          "criteria": [
            "로그를 봤다는 사실이나 스케줄러 중복 실행이라는 결론만 말하고 근거가 된 흔적을 제시하지 못한다.",
            "실행 시점이나 서버별 실행 관계가 드러나지 않는다.",
            "로그 흔적과 알림 중복 발송 사이의 연결을 설명하지 못하거나 근거 없이 원인을 단정한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P02",
  "interviews": [
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "여러 이해관계자의 요청을 목적에 따라 정리하여 요구사항의 구현 범위를 구체화하는지 검증한다. 인터뷰 요청 중 구현할 범위를 정한 판단 기준에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "세탁소 인터뷰에서 서비스에 반영할 여러 요청을 수집한 상황이다.",
          "task": "수집한 요청을 정리하여 요구사항 정의서에 담을 구현 범위를 정해야 했다.",
          "action": "요청의 목적과 해결할 문제를 파악하고, 이를 기준으로 포함하거나 제외할 범위를 구분한 판단을 설명한다.",
          "result": "요청을 정리한 기준과 실제로 정한 구현 범위의 연결이 구체적으로 드러난다."
        },
        "expectedEvidence": [
          "인터뷰 요청 중 구현할 범위를 정한 기준",
          "그 기준의 근거가 된 요청 내용과 해결하려던 문제",
          "해당 기준에 따라 요구사항에 포함하거나 제외한 구체적인 범위"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 세탁소 5곳 인터뷰로 요구사항 정의서를 쓰셨던데요, 인터뷰 요청 중 구현할 범위는 무엇을 기준으로 정하셨어요?",
      "answerTip": "당시 사례 하나를 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "구현 범위를 정한 기준을 구체적으로 제시한다.",
            "인터뷰 요청과 해결하려던 문제가 해당 기준으로 이어진 이유를 설명한다.",
            "요구사항에 포함하거나 제외한 범위를 제시하여 기준이 실제 범위 결정에 적용되었음을 보여 준다."
          ]
        },
        "acceptable": {
          "criteria": [
            "구현 범위를 정한 기준은 제시하지만 요청 내용이나 해결하려던 문제와의 연결이 부분적으로만 드러난다.",
            "포함하거나 제외한 범위를 언급하지만 기준을 적용한 설명이 구체적이지 않다."
          ]
        },
        "poor": {
          "criteria": [
            "요청을 수집했다는 설명에 그치고 구현 범위를 정한 기준을 제시하지 못한다.",
            "요청 내용, 해결하려던 문제, 정한 범위 사이의 연결을 확인하기 어렵다."
          ]
        }
      }
    },
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "예외 상황을 구현 가능한 화면 흐름으로 구체화하는지 검증한다. 화면설계서에서 예외 상황의 상태와 전환을 정한 설계 결정 하나에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "예약 서비스의 기능 흐름과 예외 상황을 화면설계서에 작성한 상황이다.",
          "task": "예외 상황에서도 사용자의 진행 상태가 분명해지도록 화면 흐름을 설계해야 했다.",
          "action": "가장 고민한 설계 결정 하나를 중심으로 예외 발생 조건과 이에 따른 화면 상태 또는 전환을 구체적으로 설명한다.",
          "result": "예외 상황을 화면 흐름으로 표현한 설계 결정과 그 이유가 구체적으로 드러난다."
        },
        "expectedEvidence": [
          "예외 상황의 화면 흐름에서 가장 고민한 설계 결정 하나",
          "그 결정이 필요했던 예외 발생 조건",
          "화면설계서에 정한 화면 상태 또는 전환과 해당 설계를 선택한 이유"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서는 화면설계서 28장을 작성하셨던데요, 예외 상황의 화면 흐름 중 가장 고민하신 설계 결정은 뭐였어요?",
      "answerTip": "기억나는 장면 하나로 설명해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "예외 상황의 화면 흐름에 관한 설계 결정 하나를 명확히 제시한다.",
            "해당 예외가 발생하는 조건을 구체적으로 설명한다.",
            "화면설계서에 정한 상태 또는 전환을 설명하고, 그 선택이 예외 조건에 적합한 이유를 제시한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "예외 상황에 관한 설계 결정을 제시하지만 발생 조건의 설명이 부분적이다.",
            "화면 상태 또는 전환을 설명하지만 구체적인 설계 내용이나 선택 이유가 충분하지 않다."
          ]
        },
        "poor": {
          "criteria": [
            "예외 상황을 고려했다는 설명에 그치고 구체적인 설계 결정을 제시하지 못한다.",
            "예외 발생 조건과 화면 상태 또는 전환의 연결을 확인하기 어렵다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "투약 전 처방 용량 확인에서 발견한 이상을 근거로 투약을 중단하는 판단을 검증한다. 평소와 다른 처방을 그대로 수행하지 않기로 결정한 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "수술 후 환자의 진통제 처방 용량이 평소 용량의 두 배로 입력된 상황이 제시된다.",
          "task": "해당 처방대로 투약해도 되는지 확인해야 했던 판단 지점이 드러난다.",
          "action": "처방 용량을 확인한 내용과 투약 중단 판단의 근거를 설명한다.",
          "result": "확인되지 않은 처방의 수행을 보류한 판단과 그 근거의 연결이 구체적으로 드러난다."
        },
        "expectedEvidence": [
          "진통제 투약을 중단하기로 판단한 구체적인 근거",
          "처방 용량의 이상을 발견하는 데 사용한 확인 내용과 비교 기준",
          "확인한 차이가 처방대로 투약하기 어렵다는 판단으로 이어진 이유"
        ]
      },
      "question": "푸른결종합병원에서 진통제 처방이 평소 용량의 두 배였던 적이 있다고 하셨는데요, 투약을 멈추기로 판단하신 근거는 뭐였어요?",
      "answerTip": "당시 장면을 떠올리며 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "투약 중단의 근거를 실제로 확인한 처방 내용에 연결해 구체적으로 설명한다.",
            "용량의 이상을 판단한 비교 기준이 분명하며, 그 차이로 인해 확인 전 투약을 보류해야 한다는 판단이 타당하게 드러난다."
          ]
        },
        "acceptable": {
          "criteria": [
            "처방 용량이 평소와 달라 투약을 중단했다는 핵심 근거는 제시한다.",
            "실제 확인한 내용이나 비교 기준이 모호해 투약 중단 판단으로 이어진 설명이 일부 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "투약을 중단한 구체적인 근거를 제시하지 못하거나 일반적인 투약 원칙만 설명한다.",
            "무엇을 확인해 처방이 의심스럽다고 판단했는지 드러나지 않는다."
          ]
        }
      }
    },
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "관찰한 환자 상태를 이전 상태와 비교하여 변화 여부를 판단하고 간호기록에 반영하는 행동을 검증한다. 활력징후와 통증의 변화를 기록한 기준에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "푸른결종합병원에서 수술 후 환자의 활력징후와 통증을 관찰하고 기록한 업무 맥락이 제시된다.",
          "task": "관찰 내용을 환자 상태의 변화로 판단하여 기록할 기준이 필요했던 점이 드러난다.",
          "action": "관찰한 수치나 환자의 호소를 이전 상태 또는 적용한 관찰 기준과 비교해 기록한 판단을 설명한다.",
          "result": "환자 상태의 변화 여부를 기록한 기준과 그 적용이 구체적으로 드러난다."
        },
